#!/usr/bin/env python3
"""
Round 184b (culprits), 5 October 2026. Needs round 183b.

Glass Garden in the Frutiger Aero look.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 184b (5 October)\n\nNeeds round 184o (guards on its heading; re-made after round 184o, whose test checks sat in the same place). No tiles patch. No app.js?v= bump.\n\n- Owner asked for Glass Garden in a Frutiger Aero / Y2K eco-tech look:\n  translucent aquamarine glass, soft light blooms, pale mint and icy teal\n  plants with a frosted sheen, glowing water, and a light-filled space round\n  the globe with soft rays and lens flares.\n- Plants lighter (icy teal to pale mint, hue 166 and up, kept under the\n  bright-green test), lit more by density; a frosted-glass sheen (frost 0.08)\n  over land; water and sea brighter aquamarine to deep cyan.\n- New layers: outline-lumen-shelf (shelves and reefs glow aquamarine under\n  the surface) and outline-lumen-gloss (sea-dem hillshade, highlights only:\n  a glossy sheen on land and sea floor).\n- Sky paler aqua to white. lumenAura: a canvas #lumen-aura just behind the\n  map, over #stars: deep teal at the window's corners to near white at the\n  globe's rim, blurred rays from behind the globe on its north-west side,\n  three faint lens rings on the far side. Globe only (not the flat map), off\n  with the hologram or Eyes (#map.away), redrawn on move/resize/idle, still.\n- Not seen against the real imagery (EOX blocked here); the aura was drawn\n  in Chromium on a stand-in globe.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round184b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 184o" not in h.read_text(encoding="utf-8"):
        sys.exit("round184b: round 184o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round184b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round184b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round184b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
